import collections
W=(47332,59332)
def closures(evs, delta=800):
    # adjacency: for each node, list of (neighbor, t)
    # count triangles where edge (a,b) at t3 closes wedge a-c-b with max(t1,t2)<=t3<=max+delta
    adj=collections.defaultdict(list)
    for u,v,t in evs:
        adj[u].append((v,t)); adj[v].append((u,t))
    res=[]
    for u,v,t3 in evs:
        # common contacts
        cu={}
        for c,t in adj[u]:
            if t<=t3 and c!=v:
                cu[c]=max(cu.get(c,-1),t) if False else min(cu.get(c,10**9),t) if False else cu.get(c,t)
        # simpler: earliest time
        cu={}
        for c,t in adj[u]:
            if t<=t3 and c!=v and (c not in cu or t<cu[c]): cu[c]=t
        cv={}
        for c,t in adj[v]:
            if t<=t3 and c!=u and (c not in cv or t<cv[c]): cv[c]=t
        for c in set(cu)&set(cv):
            m=max(cu[c],cv[c])
            if 0<=t3-m<=delta:
                res.append((u,v,t3,c,m))
                break
    return res
